package com.bautruc.ecommerce.payment.application;
import java.time.Instant;import com.bautruc.ecommerce.common.exception.ConflictException;import com.bautruc.ecommerce.payment.domain.Payment;import com.bautruc.ecommerce.payment.infrastructure.PaymentJpaRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentCommandService{private final PaymentJpaRepository payments;public PaymentCommandService(PaymentJpaRepository p){payments=p;}@Transactional public Payment createPending(Long orderId,long amount,Instant now){if(payments.findByOrderId(orderId).isPresent())throw new ConflictException(PaymentErrorCodes.PAYMENT_INVALID_STATE,"Payment already exists for order.");return payments.save(new Payment(orderId,amount,now));}}
